offers=list(csv.DictReader((R/'local_schedule_offers.csv').open()))
dated=defaultdict(list);dow={'Пн':0,'Вт':1,'Ср':2,'Чт':3,'Пт':4,'Сб':5,'Вс':6}
for x in offers:
    if x['valid_from']=='UNKNOWN' or x['origin']=='UNKNOWN' or x['destination']=='UNKNOWN':continue
    d=date.fromisoformat(x['valid_from']);end=date.fromisoformat(x['valid_to'])
    weekdays=set(range(7)) if x['weekdays_ru']=='ежедневно' else {dow[w] for w in x['weekdays_ru'].split(', ') if w in dow}
    while d<=end:
        if d.weekday() in weekdays:dated[(x['origin'],x['destination'],x['flight'],d.isoformat())].append(x)
        d+=timedelta(days=1)
conflicts=[]
for key,v in sorted(dated.items()):
    clocks=sorted({x['station_clock_local'] for x in v})
    if len(clocks)>1:conflicts.append({'origin':key[0],'destination':key[1],'flight':key[2],'date':key[3],'clock_values':'|'.join(clocks),'source_row_ids':'|'.join(x['offer_row_id'] for x in v),'units':'кандидат расписания на дату','period':key[3],'coverage':'только локальный extract; не физические кресла','status':'CLOCK_CONFLICT_NO_CHOSEN_TIME','source_id':'|'.join(sorted({x['source_id'] for x in v}))})
table('local_schedule_conflicts.csv',conflicts or [{'status':'NONE_FOUND_IN_EXTRACT','source_id':'SCHEDULE_*'}])

