def km(a,b):
    x,y=coords[a],coords[b];p1,p2=map(math.radians,[x[0],y[0]]);dp=math.radians(y[0]-x[0]);dl=math.radians(y[1]-x[1]);return 6371*2*math.asin(math.sqrt(math.sin(dp/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2))
